import type { CSSProperties } from "react";
import { AreaKey } from "@/lib/db";

// Icon artwork for the five practice areas. flag-hole doubles for both
// chipping and pitching — both are shots played at the green/hole, and the
// distinction between them lives in the label next to the icon, not in the
// icon itself. driver / iron / putter are one each for their own area.
// Supplied as SVGs (public/*.svg) with fill="currentColor" already baked
// in, so the path data is inlined here rather than loaded via <img src>:
// an <img>-loaded SVG can't inherit page color at all (currentColor only
// resolves against the SVG's own internal context, not the surrounding
// CSS cascade), which would have meant a fixed colour and a separate
// dark-mode filter hack, the way the single raster PNG icon used to need
// before this swap. Inlined, these behave exactly like any other icon in
// the app — tinted by whatever .icon-tile / color prop context they sit in.
export function AreaIcon({
  area, size = 20, color, className, style,
}: {
  area: AreaKey;
  size?: number;
  color?: string;
  className?: string;
  style?: CSSProperties;
}) {
  return (
    <svg
      viewBox="0 0 512 512"
      width={size}
      height={size}
      className={"msr area-icon" + (className ? " " + className : "")}
      style={{ color, ...style }}
      aria-hidden
    >
      <path fill="currentColor" d={PATHS[area]} />
    </svg>
  );
}

